module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    input wire enable,  
    input wire trigger,  
    output reg timeout_signal  
);  
    parameter TIMEOUT_THRESHOLD = 5;  
    reg [2:0] counter; // 3 bits to count up to 7 (0 to 7)  
    reg timer_active;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 0;  
            timeout_signal <= 0;  
            timer_active <= 0;  
        end else if (enable) begin  
            if (timer_active) begin  
                if (trigger) begin  
                    counter <= 0; // reset counter on trigger  
                end else if (counter < TIMEOUT_THRESHOLD) begin  
                    counter <= counter + 1;  
                end else begin  
                    timeout_signal <= 1; // timeout occurs  
                end  
            end else if (trigger) begin  
                timer_active <= 1;  
            end  
        end  
    end  
endmodule

