module kalman_filter (  
    input wire clk,  
    input wire [15:0] pos_meas,  
    input wire [15:0] vel_meas,  
    output reg [15:0] pos_est  
);  
    reg [15:0] x;   // state estimate  
    reg [15:0] p;   // estimation error covariance  
    reg [15:0] q = 16'd1;  // process noise covariance  
    reg [15:0] r = 16'd10; // measurement noise covariance  
    reg [15:0] k;          // Kalman gain  

    initial begin  
        x = 16'd0;  
        p = 16'd1;  
    end  

    always @(posedge clk) begin  
        // Prediction update  
        x = x + vel_meas;  
        p = p + q;  

        // Measurement update  
        k = p / (p + r);  
        x = x + k * (pos_meas - x);  
        p = (1 - k) * p;  

        pos_est = x;  
    end  
endmodule

