module serializer (
    input wire clk,
    input wire reset,
    input wire enable,
    input wire [15:0] parallel_in,
    output reg serial_out
);
    reg [3:0] bit_count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            bit_count <= 4'b0000;
            serial_out <= 1'b0;
        end else if (enable) begin
            if (bit_count < 16) begin
                serial_out <= parallel_in[15 - bit_count];
                bit_count <= bit_count + 1;
            end else begin
                serial_out <= 1'b0; // Output 0 after serialization is done
            end
        end
    end
endmodule

