module sr_flip_flop (  
    input wire S,  
    input wire R,  
    input wire clk,  
    output reg Q  
);  
    always @(posedge clk or posedge S or posedge R) begin  
        if (R) begin  
            Q <= 0;  
        end else if (S) begin  
            Q <= 1;  
        end  
        // If both S and R are high, do nothing (invalid state)  
    end  
endmodule

