module chebyshev_filter (
    input wire clk,
    input wire reset,
    input wire x,  // Input signal
    output reg y   // Output signal
);
    reg [1:0] state;  // 2-bit state to hold filter states
    reg [1:0] delay;  // 2-bit delay line

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 2'b00;
            delay <= 2'b00;
            y <= 1'b0;
        end else begin
            delay <= {delay[0], x}; // Shift the input into delay line
            // 2nd-order Chebyshev filter equation (simplified)
            y <= (state[0] & delay[0]) ^ (state[1] & delay[1]);
            state <= {state[0], y}; // Update state with output
        end
    end
endmodule

