module divide_by_8 (  
    input clk,  
    input rst,  
    input in,  
    output reg out  
);  
    reg [2:0] count;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            count <= 3'b000;  
            out <= 1'b0;  
        end else begin  
            if (in) begin  
                count <= count + 1;  
                if (count == 3'b111) begin  
                    out <= 1'b1;  
                end else begin  
                    out <= 1'b0;  
                end  
            end  
        end  
    end  
endmodule

