module lzw_compressor(
    input clk,
    input rst,
    input [7:0] data_in,
    input data_valid,
    output reg [11:0] code_out,
    output reg code_valid
);
    reg [11:0] dictionary[0:255];
    reg [11:0] next_code;
    reg [7:0] current_string[0:15];
    reg [3:0] string_length;

    initial begin
        next_code = 256; // Initialize next_code to 256
        code_valid = 0;
        string_length = 0;
    end

    always @(posedge clk or posedge rst) begin
        if (rst) begin
            next_code <= 256;
            code_valid <= 0;
            string_length <= 0;
        end else if (data_valid) begin
            // LZW processing logic
            // (Simplified for illustration purposes)
            if (string_length == 0) begin
                current_string[string_length] <= data_in;
                string_length <= string_length + 1;
            end else if (dictionary[current_string[string_length - 1]] == data_in) begin
                if (next_code < 4096) begin
                    code_out <= next_code; // Output the code
                    code_valid <= 1;
                    next_code <= next_code + 1;
                end
            end else begin
                current_string[string_length] <= data_in;
                string_length <= 1; // Reset to start new sequence
            end
        end else begin
            code_valid <= 0; // Set code_valid low when not valid
        end
    end
endmodule

