module temperature_shutdown (  
    input wire clk,  
    input wire reset,  
    input wire [7:0] temperature,  
    output reg shutdown  
);  
    parameter THRESHOLD = 8'd75;  
    parameter DURATION = 8'd5;  

    reg [3:0] count;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            shutdown <= 0;  
            count <= 0;  
        end else begin  
            if (temperature > THRESHOLD) begin  
                if (count < DURATION) begin  
                    count <= count + 1;  
                end  
                if (count == DURATION) begin  
                    shutdown <= 1;  
                end  
            end else begin  
                count <= 0;  
                shutdown <= 0;  
            end  
        end  
    end  
endmodule

