module deserializer(  
    input wire clk,  
    input wire rst,  
    input wire serial_in,  
    output reg [31:0] parallel_out  
);  
    reg [4:0] bit_count;  
    reg [31:0] shift_reg;  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            bit_count <= 0;  
            shift_reg <= 0;  
            parallel_out <= 0;  
        end else begin  
            shift_reg <= {shift_reg[30:0], serial_in};  
            bit_count <= bit_count + 1;  
            if (bit_count == 31) begin  
                parallel_out <= shift_reg;  
                bit_count <= 0;  
            end  
        end  
    end  
endmodule

