module md5_simple (
    input clk,
    input reset,
    input [63:0] data_in,
    input data_valid,
    output reg [31:0] hash_out
);
    reg [31:0] state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= 32'h0;
            hash_out <= 32'h0;
        end else if (data_valid) begin
            // Simple MD5-like transformation
            state <= state + data_in[31:0] ^ data_in[63:32];
            hash_out <= state ^ (state << 7) ^ (state >> 3);
        end
    end
endmodule

