module watchdog_timer(  
    input wire clk,  
    input wire reset,  
    input wire enable,  
    input wire manual_reset,  
    output reg timeout  
);  

    parameter TIMEOUT_PERIOD = 8'd100;  
    reg [7:0] counter;  

    always @(posedge clk or posedge reset) begin  
        if (reset) begin  
            counter <= 8'd0;  
            timeout <= 1'b0;  
        end else if (manual_reset) begin  
            counter <= 8'd0;  
            timeout <= 1'b0;  
        end else if (enable) begin  
            if (counter < TIMEOUT_PERIOD) begin  
                counter <= counter + 1;  
                timeout <= 1'b0;  
            end else begin  
                timeout <= 1'b1;  
            end  
        end  
    end  
endmodule

