module viterbi_decoder (
    input clk,
    input reset,
    input bit_in,
    output reg [1:0] decoded_out
);
    reg [1:0] state; // Current state
    reg [1:0] next_state; // Next state
    reg [1:0] path_metric [0:3]; // Path metrics for 4 states
    reg [1:0] best_prev; // Best previous state

    // State encoding
    parameter S0 = 2'b00, S1 = 2'b01, S2 = 2'b10, S3 = 2'b11;

    // State transition
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= S0;
            decoded_out <= 2'b00; // Reset output
        end else begin
            state <= next_state;
            decoded_out <= best_prev; // Output the best previous state (decoded)
        end
    end

    always @(*) begin
        // Default values
        next_state = state;
        best_prev = S0; // Default to state S0
        path_metric[0] = 0; // Initialize path metrics

        // Update path metrics based on input
        case (state)
            S0: begin
                path_metric[0] = (bit_in == 0) ? 0 : 1;
                path_metric[1] = (bit_in == 0) ? 1 : 0;
                next_state = (bit_in == 0) ? S0 : S1;
                best_prev = S0;
            end
            S1: begin
                path_metric[0] = (bit_in == 0) ? 2 : 3;
                path_metric[1] = (bit_in == 0) ? 3 : 2;
                next_state = (bit_in == 0) ? S2 : S3;
                best_prev = S1;
            end
            S2: begin
                path_metric[0] = (bit_in == 0) ? 1 : 2;
                path_metric[1] = (bit_in == 0) ? 0 : 3;
                next_state = (bit_in == 0) ? S3 : S0;
                best_prev = S2;
            end
            S3: begin
                path_metric[0] = (bit_in == 0) ? 3 : 0;
                path_metric[1] = (bit_in == 0) ? 2 : 1;
                next_state = (bit_in == 0) ? S1 : S2;
                best_prev = S3;
            end
            default: begin
                next_state = S0; // Default state
                best_prev = S0;
            end
        endcase
    end
endmodule

