module goertzel (
    input clk,
    input reset,
    input [15:0] sample,
    input start,
    output reg detected
);
    parameter TARGET_FREQ = 200; // Frequency to detect
    parameter SAMPLE_RATE = 1000; // Sample rate in Hz
    parameter N = 128; // Number of samples
    parameter K = (TARGET_FREQ * N) / SAMPLE_RATE;

    reg [15:0] Xn;
    reg [15:0] Xn1, Xn2;
    reg [7:0] count;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            Xn <= 0;
            Xn1 <= 0;
            Xn2 <= 0;
            count <= 0;
            detected <= 0;
        end else if (start) begin
            if (count < N) begin
                Xn2 <= Xn1;
                Xn1 <= Xn;
                Xn <= sample + 2 * Xn1 - Xn2;
                count <= count + 1;
            end else begin
                // Process the results and set detected
                if (Xn1 > 10000) // Threshold for detection
                    detected <= 1;
                else
                    detected <= 0;
                count <= 0; // Reset count for the next round
            end
        end
    end
endmodule

