module shift_register(clk, rst, shift_left, data_in, q);  
  input clk;  
  input rst;  
  input shift_left;  
  input data_in;  
  output reg [15:0] q;  

  always @(posedge clk or posedge rst) begin  
    if (rst)  
      q <= 16'b0;  
    else if (shift_left)  
      q <= {q[14:0], data_in};  
    else  
      q <= {data_in, q[15:1]};  
  end  
endmodule

