module pwm_generator(  
    input clk,  
    input rst,  
    input [7:0] duty_cycle,  
    output reg pwm_signal  
);  
    reg [9:0] counter;  
    parameter PERIOD = 1000; // 1 ms period at 1 kHz clock  

    always @(posedge clk or posedge rst) begin  
        if (rst) begin  
            counter <= 0;  
            pwm_signal <= 0;  
        end else begin  
            if (counter < PERIOD)  
                counter <= counter + 1;  
            else  
                counter <= 0;  

            if (counter < (duty_cycle * PERIOD / 100))  
                pwm_signal <= 1;  
            else  
                pwm_signal <= 0;  
        end  
    end  
endmodule

